changeSet.sql:
ALTER TABLE saga_step_result ADD COLUMN IF NOT EXISTS step_started_at timestamptz;
CREATE TABLE IF NOT EXISTS saga_step_call ( id bigserial NOT NULL, saga_id uuid NOT NULL, step_name text NOT NULL, phase text NOT NULL, attempt integer NOT NULL DEFAULT 0, request_url text, request_body jsonb, status_code integer, response_body jsonb, error text, step_started_at timestamptz NOT NULL, created_at timestamptz NOT NULL, started_at timestamptz NOT NULL, PRIMARY KEY (id, started_at) ) PARTITION BY RANGE (started_at);
CREATE INDEX IF NOT EXISTS idx_saga_step_call_saga_id_started_at ON saga_step_call (saga_id, started_at);

CREATE TABLE IF NOT EXISTS saga_join_barrier ( parent_id uuid NOT NULL, parent_started_at timestamptz NOT NULL, split_node_id text NOT NULL, join_node_id text NOT NULL, expected_count integer NOT NULL, arrived_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL, PRIMARY KEY (parent_id, parent_started_at, split_node_id) );
CREATE TABLE IF NOT EXISTS saga_join_branch ( id bigserial NOT NULL PRIMARY KEY, parent_id uuid NOT NULL, parent_started_at timestamptz NOT NULL, split_node_id text NOT NULL, branch_id text NOT NULL, child_id uuid NOT NULL, child_started_at timestamptz NOT NULL, created_at timestamptz NOT NULL );
CREATE INDEX IF NOT EXISTS idx_saga_join_branch_parent ON saga_join_branch (parent_id, parent_started_at, split_node_id);

ALTER TABLE saga_join_branch ADD COLUMN IF NOT EXISTS arrived_at timestamptz;
-- Defensive: a pre-fix split-step redelivery (before the ON CONFLICT on this -- table's INSERT existed) could have left duplicate rows for the same logical -- branch with different child_id. Keep only the earliest row per branch identity -- so the UNIQUE constraint below can never fail on pre-existing data. DELETE FROM saga_join_branch a USING saga_join_branch b WHERE a.parent_id = b.parent_id AND a.parent_started_at = b.parent_started_at AND a.split_node_id = b.split_node_id AND a.branch_id = b.branch_id AND a.id > b.id;
DO $$ BEGIN IF NOT EXISTS ( SELECT 1 FROM pg_constraint WHERE conname = 'uq_saga_join_branch_identity' ) THEN ALTER TABLE saga_join_branch ADD CONSTRAINT uq_saga_join_branch_identity UNIQUE (parent_id, parent_started_at, split_node_id, branch_id); END IF; END $$;
